// === Tab: Stripes ===
class Stripe {
	constructor(numPts = 4, numStripes = 10, clr = "deeppink") {
		this.numPts = numPts;
		this.numStripes = numStripes;
		this.clr = clr;
		this.crv1 = this.genCurve(0.2, 0.2);
		this.crv2 = this.genCurve(0.9, 0.1);
		this.polys = [];
		// console.log(this)
	}

	genCurve(base, dev) {
		let crv = {
			xs: this.genXs(this.numPts),
			ys: this.genYs(this.numPts, base, dev),
			clr: epiColors.getRandomClr()
		}
		// console.log(crv.xs);
		return crv;
	}

	draw() {
		this.polys = [];
		for (let i = 0; i < this.numStripes; i++) {
			const f = i/(this.numStripes-1);
			/*
			const f2 = f1*f1
			const ft = (frameCount%100)/100;
			var f = abs(sin(f1*PI+frameCount/200)); // lerp(f1, f2, ft);
			*/
			const pts = [], xs = [], ys = [];
			for (let j = 0; j < this.numPts; j++) {
				xs.push(lerp(this.crv1.xs[j], this.crv2.xs[j], f));
				ys.push(lerp(this.crv1.ys[j], this.crv2.ys[j], f));
			}
			var crv = {
				pts, xs, ys,
				clr: lerpColor(this.crv1.clr, this.crv2.clr, f)
			}
			// console.log(crv)
			// drawCurve(crv);
			const poly = new Polygon(this.getCurvePts(crv));
			this.polys.push(poly);
			stroke(this.clr);
			poly.drawShape();
		}
	}

	getCurvePts(crv, debug = false) {
		var pts = [];
		for (let i = 0; i < crv.xs.length-3; i++) {
			const x1 = crv.xs[i+0], y1 = crv.ys[i+0];
			const x2 = crv.xs[i+1], y2 = crv.ys[i+1];
			const x3 = crv.xs[i+2], y3 = crv.ys[i+2];
			const x4 = crv.xs[i+3], y4 = crv.ys[i+3];
			const len = dist(x2, y2, x3, y3);
			const num = ~~max(2, len/5);
			for (let j = 0; j < num; j++) {
				var f = j/num;
				const x = curvePoint(x1, x2, x3, x4, f);
				const y = curvePoint(y1, y2, y3, y4, f);
				pts.push({x, y});
			}
		}
		var x = crv.xs[crv.xs.length-2];
		var y = crv.ys[crv.ys.length-2];
		pts.push({x, y});

		return pts;
	}



	genXs(num, minX = 0, maxX = width) {
		const arr = [];
		let lclMin = Infinity, lclMax = -Infinity;
		for (let i = 0; i < num; i++) {
			var x = random()*width;
			arr.push(x);
			if (x < lclMin) lclMin = x;
			if (x > lclMax) lclMax = x;		
		}
		for (let i = 0; i < num; i++) {
			var x = map(arr[i], lclMin, lclMax, minX, maxX);
			arr[i] = x;
		}

		arr.sort((a, b) => a - b);
		// arr[0] = width * random(0.1);
		// arr[num-1] = width * random(0.9, 1);
		arr[1] = width * random(0.15);
		arr[num-2] = width * random(0.85, 1);

		return arr;
	}
	genYs(num, base = 0.5, dev = 0.2) {
		const d2 = dev/2;
		var arr = [];
		for (let i = 0; i < num; i++) arr.push((random(-d2, d2)+base)*height); 
		// arr[0] = random(0.4, 0.6)*height;
		// arr[num-1] = random(0.2, 0.8)*height;
		return arr;
	}
}

