		saveSvg("epi_curve_lines");
	}
}

function saveSvg(file_name) {
	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;

	for (let stripe of stripes) {		
		svgStr += `<g id="${stripe.clr}" stroke="${stripe.clr}" fill="none">\n`;
		for (const poly of stripe.polys) {
			svgStr += poly.toSVG();
		}
		svgStr += `</g>\n`;
	}

	svgStr += `</svg>`;

	save(svgStr.split("\n"), file_name + '.svg.txt');
}

