const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
let epiColors;

const PENS = ["cyan", "deeppink", "pink"]; // (["pink", "deeppink", "cyan"]).reverse();
let NUM_POINTS = 6;
const NUM_LINES = 55; 
let stripes;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("lerping between 2 curves");
	loop();
	noFill();
	stroke(212);
	strokeWeight(2);

	epiColors = new EpiColors();
	epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);
	// console.log(epiColors)

	stripes =  [];
	for (const CLR of PENS) {	
		stripes.push(new Stripe(NUM_POINTS, NUM_LINES, CLR));
	}

	// noLoop() removed for animation
}

function draw() {
	blendMode(BLEND)
	background(4, 4, 12); // epiColors.BG
	blendMode(ADD);

	for (const stripe of stripes) {	
		stripe.draw();
	}
}


function mousePressed() {
